insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A prestação pecuniária consiste no pagamento em dinheiro à vítima ou à entidade pública ou privada com fim social, de importância fixada pelo juiz, não inferior a um salário mínimo nem superior a trezentos e sessenta salários mínimos. O valor pago será deduzido do montante de eventual reparação civil.', '["Pagamento à vítima ou entidade com fim social.","De um a trezentos e sessenta salários mínimos.","Deduzida da reparação civil."]'::jsonb, '["Teto de trezentos e sessenta salários mínimos."]'::jsonb, 'O juiz fixa o pagamento a uma entidade ambiental, abatido da indenização.', '["Assertiva que fixa o teto em cem salários mínimos erra: são trezentos e sessenta."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-12'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O recolhimento domiciliar baseia-se na autodisciplina e senso de responsabilidade do condenado, que deverá, sem vigilância, trabalhar, frequentar curso ou exercer atividade autorizada, permanecendo recolhido nos dias e horários de folga em residência ou local de moradia habitual, conforme a sentença.', '["Autodisciplina e senso de responsabilidade.","Sem vigilância.","Recolhimento nos dias e horários de folga."]'::jsonb, '["Não há vigilância direta."]'::jsonb, 'O condenado trabalha de dia e se recolhe em casa nos fins de semana.', '["Assertiva que exige monitoramento constante no recolhimento domiciliar erra: ele é sem vigilância."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-13'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São circunstâncias que atenuam a pena o baixo grau de instrução ou escolaridade do agente; o arrependimento do infrator, manifestado pela espontânea reparação do dano ou limitação significativa da degradação ambiental; a comunicação prévia pelo agente do perigo iminente de degradação ambiental; e a colaboração com os agentes encarregados da vigilância e do controle ambiental.', '["Baixa escolaridade.","Arrependimento com reparação do dano.","Comunicação prévia do perigo.","Colaboração com a fiscalização."]'::jsonb, '["Baixo grau de instrução é atenuante típica desta Lei."]'::jsonb, 'Quem repara espontaneamente o dano tem a pena atenuada.', '["Assertiva que não admite atenuante pela colaboração com a fiscalização erra."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-14'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São circunstâncias que agravam a pena, quando não constituem ou qualificam o crime, a reincidência nos crimes ambientais e o fato de o agente ter cometido a infração para obter vantagem pecuniária; coagindo outrem; afetando gravemente a saúde pública ou o meio ambiente; concorrendo para danos à propriedade alheia; atingindo unidades de conservação ou áreas de regime especial; atingindo áreas urbanas; em período de defeso; em domingos ou feriados; à noite; em épocas de seca ou inundações; no interior de espaço territorial protegido; com métodos cruéis; mediante fraude ou abuso de confiança; com abuso de licença; no interesse de pessoa jurídica mantida por verbas públicas; atingindo espécies ameaçadas; ou com facilitação de funcionário público.', '["Reincidência em crimes ambientais.","Motivação econômica, coação, fraude e abuso de confiança.","Local e época: unidades de conservação, áreas urbanas, defeso, noite, domingos, feriados, seca e inundações.","Métodos cruéis e espécies ameaçadas."]'::jsonb, '["Agravantes só valem quando não constituem ou qualificam o crime."]'::jsonb, 'Pescar em período de defeso agrava a pena.', '["Assertiva que aplica as agravantes mesmo quando já integram o tipo erra."]'::jsonb, '[{"termo":"Defeso","significado":"Período em que a pesca ou a caça de certas espécies é proibida."}]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-15'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes da Lei, a suspensão condicional da pena pode ser aplicada nos casos de condenação a pena privativa de liberdade não superior a três anos.', '["Sursis para pena privativa de liberdade não superior a três anos."]'::jsonb, '["Limite de três anos (maior do que o do Código Penal comum)."]'::jsonb, 'Condenado a três anos por crime ambiental pode ter a pena suspensa.', '["Assertiva que fixa em dois anos o limite do sursis ambiental erra: são três anos."]'::jsonb, '[]'::jsonb, '["Art. 17"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-16'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A verificação da reparação a que se refere o §2º do art. 78 do Código Penal será feita mediante laudo de reparação do dano ambiental, e as condições a serem impostas pelo juiz deverão relacionar-se com a proteção ao meio ambiente.', '["Laudo de reparação do dano ambiental.","Condições do sursis ligadas à proteção ambiental."]'::jsonb, '["Verificação por LAUDO."]'::jsonb, 'O juiz exige laudo que comprove a recuperação da área degradada.', '["Assertiva que dispensa o laudo de reparação erra."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-17'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A multa será calculada segundo os critérios do Código Penal; se revelar-se ineficaz, ainda que aplicada no valor máximo, poderá ser aumentada até três vezes, tendo em vista o valor da vantagem econômica auferida.', '["Cálculo pelo Código Penal.","Aumento até três vezes se ineficaz."]'::jsonb, '["Triplicação da multa em caso de ineficácia."]'::jsonb, 'Se a multa máxima é pouca diante do lucro do crime, o juiz pode triplicá-la.', '["Assertiva que fixa o aumento máximo em dez vezes erra: são até três vezes."]'::jsonb, '[]'::jsonb, '["Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-18'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A perícia de constatação do dano ambiental, sempre que possível, fixará o montante do prejuízo causado para efeitos de prestação de fiança e cálculo de multa. A perícia produzida no inquérito civil ou no juízo cível poderá ser aproveitada no processo penal, instaurando-se o contraditório.', '["Perícia fixa o montante do prejuízo.","Aproveitamento da perícia civil no processo penal, com contraditório."]'::jsonb, '["Prova emprestada com contraditório."]'::jsonb, 'A perícia do inquérito civil é reaproveitada na ação penal.', '["Assertiva que veda o aproveitamento da perícia civil no processo penal erra."]'::jsonb, '[]'::jsonb, '["Art. 20"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-19'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A sentença penal condenatória, sempre que possível, fixará o valor mínimo para reparação dos danos causados pela infração, considerando os prejuízos sofridos pelo ofendido ou pelo meio ambiente. Transitada em julgado, a execução poderá efetuar-se pelo valor fixado, sem prejuízo da liquidação para apuração do dano efetivamente sofrido.', '["Valor mínimo de reparação fixado na sentença.","Execução imediata pelo valor mínimo.","Liquidação do dano efetivo."]'::jsonb, '["Reparação MÍNIMA na sentença penal."]'::jsonb, 'A sentença já fixa uma indenização mínima pelo dano à floresta.', '["Assertiva que impede a liquidação do dano efetivo após a sentença erra."]'::jsonb, '[]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-20'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas aplicáveis isolada, cumulativa ou alternativamente às pessoas jurídicas são a multa, as restritivas de direitos e a prestação de serviços à comunidade.', '["Multa.","Restritivas de direitos.","Prestação de serviços à comunidade."]'::jsonb, '["Pessoa jurídica não recebe pena privativa de liberdade."]'::jsonb, 'A empresa condenada paga multa e custeia projetos ambientais.', '["Assertiva que prevê prisão para a pessoa jurídica erra."]'::jsonb, '[]'::jsonb, '["Art. 22"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-21'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas restritivas de direitos da pessoa jurídica são a suspensão parcial ou total de atividades, a interdição temporária de estabelecimento, obra ou atividade e a proibição de contratar com o Poder Público e dele obter subsídios, subvenções ou doações. A suspensão aplica-se quando as atividades descumprem normas ambientais. A interdição aplica-se quando o estabelecimento funciona sem autorização ou em desacordo com ela. A proibição de contratar não pode exceder dez anos.', '["Suspensão de atividades.","Interdição de estabelecimento, obra ou atividade.","Proibição de contratar com o Poder Público por até dez anos."]'::jsonb, '["Proibição de contratar: máximo de dez anos."]'::jsonb, 'A fábrica sem licença tem o estabelecimento interditado.', '["Assertiva que fixa em cinco anos o teto da proibição de contratar erra: são dez anos."]'::jsonb, '[]'::jsonb, '["Art. 21"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-22'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A prestação de serviços à comunidade pela pessoa jurídica consistirá no custeio de programas e projetos ambientais, na execução de obras de recuperação de áreas degradadas, na manutenção de espaços públicos e em contribuições a entidades ambientais ou culturais públicas.', '["Custeio de programas ambientais.","Recuperação de áreas degradadas.","Manutenção de espaços públicos.","Contribuições a entidades ambientais ou culturais públicas."]'::jsonb, '["Quatro formas de prestação de serviços pela empresa."]'::jsonb, 'A empresa financia a recuperação de uma nascente degradada.', '["Assertiva que prevê trabalho pessoal dos sócios como serviço da pessoa jurídica erra."]'::jsonb, '[]'::jsonb, '["Art. 21"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-23'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa jurídica constituída ou utilizada, preponderantemente, com o fim de permitir, facilitar ou ocultar a prática de crime definido na Lei terá decretada sua liquidação forçada, e seu patrimônio será considerado instrumento do crime e perdido em favor do Fundo Penitenciário Nacional.', '["Liquidação forçada da empresa de fachada.","Patrimônio perdido em favor do Fundo Penitenciário Nacional."]'::jsonb, '["Destino: Fundo Penitenciário Nacional."]'::jsonb, 'A empresa criada só para acobertar o tráfico de madeira é liquidada.', '["Assertiva que destina o patrimônio ao Fundo Nacional do Meio Ambiente erra: é ao Fundo Penitenciário Nacional."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-24'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Verificada a infração, serão apreendidos seus produtos e instrumentos, lavrando-se os autos. Os animais serão prioritariamente libertados em seu habitat ou, sendo inviável por questões sanitárias, entregues a zoológicos, fundações ou entidades semelhantes. Até a entrega, o órgão autuante zelará por condições adequadas de acondicionamento e transporte. Produtos perecíveis e madeiras serão avaliados e doados a instituições científicas, hospitalares, penais e beneficentes. Produtos e subprodutos da fauna não perecíveis serão destruídos ou doados a instituições científicas, culturais ou educacionais. Os instrumentos serão vendidos, garantida a descaracterização por reciclagem.', '["Apreensão de produtos e instrumentos.","Animais libertados em seu habitat, prioritariamente.","Perecíveis e madeiras doados.","Instrumentos vendidos, com descaracterização."]'::jsonb, '["ATUALIZAÇÃO: parágrafos alterados e renumerados pela Lei nº 13.052, de 2014.","Soltura no habitat é a prioridade."]'::jsonb, 'A ave apreendida é solta na natureza, se possível.', '["Assertiva que manda destruir os animais apreendidos erra: a prioridade é a soltura no habitat."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
