insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes ambientais de menor potencial ofensivo, a proposta de aplicação imediata de pena restritiva de direitos ou multa (transação penal) somente poderá ser formulada desde que tenha havido a prévia composição do dano ambiental, salvo em caso de comprovada impossibilidade.', '["Transação penal exige prévia composição do dano ambiental.","Exceção: impossibilidade comprovada."]'::jsonb, '["Sem composição do dano, não há transação penal."]'::jsonb, 'Antes de propor a transação, o autor do crime repara o dano ambiental.', '["Assertiva que dispensa a composição do dano para a transação penal ambiental erra."]'::jsonb, '[]'::jsonb, '["Lei dos Juizados Especiais"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-27'
