insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As disposições do sursis processual da Lei dos Juizados Especiais aplicam-se aos crimes de menor potencial ofensivo da Lei com modificações: a extinção da punibilidade depende de laudo de constatação de reparação do dano ambiental; se o laudo mostrar reparação incompleta, o prazo de suspensão é prorrogado até o máximo previsto, acrescido de mais um ano, com suspensão da prescrição; no período de prorrogação não se aplicam algumas condições; findo o prazo, faz-se novo laudo, podendo haver nova prorrogação; e esgotada a prorrogação, a extinção da punibilidade depende de laudo que comprove as providências necessárias à reparação integral.', '["Sursis processual com laudo de reparação do dano.","Prorrogação por reparação incompleta, mais um ano.","Prescrição suspensa.","Extinção da punibilidade depende de laudo."]'::jsonb, '["A extinção da punibilidade exige LAUDO de reparação."]'::jsonb, 'O processo fica suspenso até o laudo comprovar a recuperação da área.', '["Assertiva que extingue a punibilidade pelo mero decurso do prazo erra: depende de laudo."]'::jsonb, '[]'::jsonb, '["Lei dos Juizados Especiais"]'::jsonb, 'under_review', 'claude'
