insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Matar, perseguir, caçar, apanhar ou utilizar espécimes da fauna silvestre, nativos ou em rota migratória, sem a devida permissão, licença ou autorização da autoridade competente, ou em desacordo com a obtida: detenção de seis meses a um ano, e multa. Incorre nas mesmas penas quem impede a procriação da fauna, quem modifica, danifica ou destrói ninho, abrigo ou criadouro natural, e quem vende, expõe à venda, exporta, adquire, guarda, tem em cativeiro ou transporta espécimes ou produtos da fauna silvestre sem autorização. Na guarda doméstica de espécie silvestre não ameaçada, o juiz pode deixar de aplicar a pena. A pena é aumentada de metade se o crime é praticado contra espécie rara ou ameaçada, em período proibido à caça, durante a noite, entre outras hipóteses.', '["Matar, caçar ou utilizar fauna silvestre sem autorização: detenção de seis meses a um ano e multa.","Equiparados: impedir procriação, destruir ninhos e comercializar fauna sem autorização.","Guarda doméstica de espécie não ameaçada: juiz pode não aplicar a pena.","Aumento de metade em hipóteses graves."]'::jsonb, '["Fauna silvestre é a que tem ciclo de vida, total ou parcial, no território ou nas águas jurisdicionais brasileiras."]'::jsonb, 'Caçar um animal silvestre sem licença é crime do art. 29.', '["Assertiva que pune sempre a guarda doméstica de qualquer espécie silvestre erra: o juiz pode deixar de aplicar a pena se a espécie não for ameaçada."]'::jsonb, '[{"termo":"Fauna silvestre","significado":"Animais nativos ou migratórios cujo ciclo de vida ocorre no território brasileiro."}]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
