insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Praticar ato de abuso, maus-tratos, ferir ou mutilar animais silvestres, domésticos ou domesticados, nativos ou exóticos: detenção de três meses a um ano, e multa. Incorre nas mesmas penas quem realiza experiência dolorosa ou cruel em animal vivo, ainda que para fins didáticos ou científicos, quando existirem recursos alternativos. Quando se tratar de cão ou gato, a pena é de reclusão de 2 a 5 anos, multa e proibição da guarda. Incorre nas mesmas penas quem realiza ou permite tatuagens e piercings em cães e gatos com fins estéticos, ou provoca desastre ambiental que prejudique animais. A pena é aumentada de um sexto a um terço se ocorre morte do animal.', '["Abuso, maus-tratos, ferir ou mutilar animais: detenção de três meses a um ano e multa.","Experiência cruel quando há alternativas.","Cão ou gato: reclusão de 2 a 5 anos, multa e proibição da guarda.","Aumento de um sexto a um terço se o animal morre."]'::jsonb, '["ATUALIZAÇÃO: a pena qualificada para cão e gato (reclusão) foi incluída pela Lei nº 14.064, de 2020 (Lei Sansão).","Maus-tratos a CÃO ou GATO: reclusão de 2 a 5 anos."]'::jsonb, 'Mutilar um cão é crime punido com reclusão.', '["Assertiva que aplica detenção aos maus-tratos contra cães e gatos erra: a pena é de reclusão de 2 a 5 anos."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
