insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Provocar, pela emissão de efluentes ou carreamento de materiais, o perecimento de espécimes da fauna aquática existentes em rios, lagos, açudes, lagoas, baías ou águas jurisdicionais brasileiras: detenção de um a três anos, ou multa, ou ambas. Incorre nas mesmas penas quem causa degradação em viveiros, açudes ou estações de aquicultura de domínio público; quem explora campos naturais de invertebrados aquáticos e algas sem licença; e quem fundeia embarcações ou lança detritos sobre bancos de moluscos ou corais demarcados em carta náutica.', '["Perecimento de fauna aquática por efluentes ou materiais.","Degradação de viveiros e açudes públicos.","Exploração sem licença de invertebrados e algas.","Danos a bancos de moluscos e corais."]'::jsonb, '["Detenção de um a três anos, ou multa, ou ambas."]'::jsonb, 'Lançar efluentes que matam peixes de um rio é crime.', '["Assertiva que prevê reclusão para esse crime erra: a pena é de detenção."]'::jsonb, '[]'::jsonb, '["Art. 34"]'::jsonb, 'under_review', 'claude'
