insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Pescar em período no qual a pesca seja proibida ou em lugares interditados por órgão competente: detenção de um a três anos, ou multa, ou ambas. Incorre nas mesmas penas quem pesca espécies que devam ser preservadas ou espécimes com tamanho inferior ao permitido; quem pesca quantidades superiores às permitidas ou mediante aparelhos, petrechos, técnicas e métodos não permitidos; e quem transporta, comercializa, beneficia ou industrializa espécimes provenientes de pesca proibida.', '["Pesca em período proibido ou em local interditado.","Espécies ou tamanhos proibidos e quantidades acima do permitido.","Comércio de pescado de origem proibida."]'::jsonb, '["Alcança também quem transporta ou comercializa o pescado ilegal."]'::jsonb, 'Pescar durante o período do defeso é crime.', '["Assertiva que alcança só o pescador, excluindo quem comercializa o pescado ilegal, erra."]'::jsonb, '[]'::jsonb, '["Art. 36"]'::jsonb, 'under_review', 'claude'
