insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Causar dano direto ou indireto às Unidades de Conservação e às áreas de que trata o decreto de regulamentação, independentemente de sua localização: reclusão de um a cinco anos. Unidades de Conservação de Proteção Integral são as Estações Ecológicas, Reservas Biológicas, Parques Nacionais, Monumentos Naturais e Refúgios de Vida Silvestre. O dano que afeta espécies ameaçadas no interior dessas unidades é circunstância agravante. Se o crime for culposo, a pena será reduzida à metade.', '["Dano direto ou indireto às unidades de conservação.","Reclusão de um a cinco anos.","Rol de unidades de proteção integral.","Agravante para espécies ameaçadas.","Culposo: metade."]'::jsonb, '["Pena de RECLUSÃO.","Rol de proteção integral: Estações Ecológicas, Reservas Biológicas, Parques Nacionais, Monumentos Naturais e Refúgios de Vida Silvestre."]'::jsonb, 'Causar dano em um Parque Nacional é crime com reclusão de um a cinco anos.', '["Assertiva que prevê detenção para dano a unidades de conservação erra: é reclusão."]'::jsonb, '[]'::jsonb, '["Art. 52"]'::jsonb, 'under_review', 'claude'
