select u.id, u.content_sha256, 'Provocar incêndio em floresta ou em demais formas de vegetação: reclusão de dois a quatro anos, e multa. Se o crime é culposo, a pena é de detenção de seis meses a um ano, e multa.', '["Incêndio em floresta ou vegetação.","Reclusão de dois a quatro anos e multa.","Culposo: detenção de seis meses a um ano."]'::jsonb, '["Dolo: reclusão; culpa: detenção."]'::jsonb, 'Ateiar fogo na mata é o crime do art. 41.', '["Assertiva que prevê detenção para o incêndio doloso erra: é reclusão."]'::jsonb, '[]'::jsonb, '["Art. 42"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-41'
