select u.id, u.content_sha256, 'Penetrar em Unidades de Conservação conduzindo substâncias ou instrumentos próprios para caça ou para exploração de produtos ou subprodutos florestais, sem licença da autoridade competente: detenção de seis meses a um ano, e multa.', '["Entrar em unidade de conservação com instrumentos de caça ou de exploração florestal sem licença."]'::jsonb, '["Crime de perigo: basta penetrar com os instrumentos."]'::jsonb, 'Entrar armado com instrumentos de caça em um parque nacional configura o crime.', '["Assertiva que exige o efetivo abate de animais erra: basta a entrada com os instrumentos."]'::jsonb, '[]'::jsonb, '["Art. 40"]'::jsonb, 'under_review', 'claude'
