insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes da seção dos crimes contra a flora, a pena é aumentada de um sexto a um terço se do fato resulta diminuição de águas naturais, erosão do solo ou modificação do regime climático, ou se o crime é cometido no período de queda das sementes, no de formação de vegetações, contra espécies raras ou ameaçadas, em época de seca ou inundação, ou durante a noite, em domingo ou feriado.', '["Aumento de um sexto a um terço nos crimes contra a flora.","Consequências: diminuição de águas, erosão e mudança climática.","Época e circunstâncias especiais."]'::jsonb, '["Aumento de um sexto a um terço."]'::jsonb, 'Desmatar à noite aumenta a pena do crime contra a flora.', '["Assertiva que fixa o aumento da metade erra: é de um sexto a um terço."]'::jsonb, '[]'::jsonb, '["Arts. 38 a 52"]'::jsonb, 'under_review', 'claude'
