insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Poluição: causar poluição de qualquer natureza em níveis tais que resultem ou possam resultar em danos à saúde humana, ou que provoquem a mortandade de animais ou a destruição significativa da flora: reclusão de um a quatro anos, e multa. Se culposo, detenção de seis meses a um ano e multa. Se o crime tornar área imprópria para a ocupação humana, causar poluição atmosférica que retire habitantes ou cause danos à saúde, causar poluição hídrica que interrompa o abastecimento público, dificultar o uso público das praias, ou ocorrer por lançamento de resíduos em desacordo com leis ou regulamentos, a pena é de reclusão de um a cinco anos. Nas mesmas penas incorre quem deixar de adotar medidas de precaução exigidas pela autoridade em caso de risco de dano ambiental grave ou irreversível.', '["Poluição que cause ou possa causar dano à saúde, mortandade de animais ou destruição da flora.","Reclusão de um a quatro anos e multa.","Culposo: detenção de seis meses a um ano.","Qualificadoras: reclusão de um a cinco anos.","Omissão de medidas de precaução."]'::jsonb, '["Crime de perigo: basta que a poluição POSSA causar dano.","Qualificadoras com pena de um a cinco anos."]'::jsonb, 'Contaminar um rio a ponto de interromper o abastecimento de água qualifica a poluição.', '["Assertiva que exige dano efetivo à saúde humana para o crime do art. 54 erra: basta a possibilidade de dano."]'::jsonb, '[]'::jsonb, '["Art. 56"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-54'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Executar pesquisa, lavra ou extração de recursos minerais sem a competente autorização, permissão, concessão ou licença, ou em desacordo com a obtida: detenção de seis meses a um ano, e multa. Nas mesmas penas quem deixa de recuperar a área pesquisada ou explorada, nos termos da autorização ou determinação do órgão competente.', '["Pesquisa, lavra ou extração mineral sem autorização.","Deixar de recuperar a área explorada.","Detenção de seis meses a um ano e multa."]'::jsonb, '["Também pune quem não recupera a área."]'::jsonb, 'O garimpo sem licença configura o crime do art. 55.', '["Assertiva que pune só a atividade sem licença, ignorando a falta de recuperação da área, erra."]'::jsonb, '[]'::jsonb, '["Art. 44"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-55'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Produzir, processar, embalar, importar, exportar, comercializar, fornecer, transportar, armazenar, guardar, ter em depósito ou usar produto ou substância tóxica, perigosa ou nociva à saúde humana ou ao meio ambiente, em desacordo com as exigências legais ou regulamentares: reclusão de um a quatro anos, e multa. Nas mesmas penas quem abandona os produtos ou os utiliza em desacordo com normas ambientais ou de segurança, ou manipula, armazena, transporta ou dá destinação final a resíduos perigosos de forma diversa da legal. Se o produto for nuclear ou radioativo, a pena é aumentada de um sexto a um terço. Se culposo, detenção de seis meses a um ano e multa.', '["Condutas com produtos ou substâncias tóxicas, perigosas ou nocivas em desacordo com a lei.","Reclusão de um a quatro anos e multa.","Resíduos perigosos com destinação irregular.","Nuclear ou radioativo: aumento de um sexto a um terço.","Culposo: detenção de seis meses a um ano."]'::jsonb, '["Tipo misto alternativo com muitos núcleos."]'::jsonb, 'Descartar resíduos químicos perigosos em lixão comum configura o crime.', '["Assertiva que isenta o armazenamento irregular de substância perigosa erra: ele é um dos núcleos do tipo."]'::jsonb, '[]'::jsonb, '["Art. 54"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-56'
