insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes dolosos previstos na seção sobre poluição e outros crimes ambientais, as penas serão aumentadas de um sexto a um terço se resulta dano irreversível à flora ou ao meio ambiente em geral; de um terço até a metade se resulta lesão corporal de natureza grave em outrem; e até o dobro se resultar a morte de outrem. As penalidades somente serão aplicadas se do fato não resultar crime mais grave.', '["Dano irreversível: um sexto a um terço.","Lesão grave: um terço até a metade.","Morte: até o dobro.","Só se não houver crime mais grave."]'::jsonb, '["Aplica-se apenas aos crimes DOLOSOS.","Subsidiário a crime mais grave."]'::jsonb, 'A poluição dolosa que causa morte de pessoa tem a pena aumentada até o dobro.', '["Assertiva que aplica os aumentos aos crimes culposos erra: valem nos crimes dolosos."]'::jsonb, '[]'::jsonb, '["Art. 54"]'::jsonb, 'under_review', 'claude'
