select u.id, u.content_sha256, 'Alterar o aspecto ou estrutura de edificação ou local especialmente protegido por lei, ato administrativo ou decisão judicial, em razão de seu valor paisagístico, ecológico, turístico, artístico, histórico, cultural, religioso, arqueológico, etnográfico ou monumental, sem autorização da autoridade competente ou em desacordo com a concedida: reclusão de um a três anos, e multa.', '["Alterar edificação ou local protegido sem autorização.","Reclusão de um a três anos e multa."]'::jsonb, '["Pune a ALTERAÇÃO, e não só a destruição."]'::jsonb, 'Reformar a fachada de um prédio tombado sem autorização é crime.', '["Assertiva que exige a destruição total do bem erra: basta a alteração do aspecto ou da estrutura."]'::jsonb, '[]'::jsonb, '["Art. 64"]'::jsonb, 'under_review', 'claude'
