insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Pichar ou por outro meio conspurcar edificação ou monumento urbano: detenção de 3 meses a 1 ano, e multa. Se o ato for realizado em monumento ou coisa tombada em virtude de valor artístico, arqueológico ou histórico, a pena é de 6 meses a 1 ano de detenção e multa. Não constitui crime o grafite realizado para valorizar o patrimônio público ou privado mediante manifestação artística, desde que consentido pelo proprietário e, no caso de bem público, autorizado pelo órgão competente, observadas as posturas municipais e as normas de preservação.', '["Pichar ou conspurcar edificação ou monumento urbano.","Detenção de 3 meses a 1 ano e multa.","Monumento ou bem tombado: 6 meses a 1 ano.","Grafite consentido e autorizado não é crime."]'::jsonb, '["ATUALIZAÇÃO: redação do artigo dada pela Lei nº 12.408, de 2011, que distinguiu pichação e grafite.","Grafite com consentimento não é crime."]'::jsonb, 'Pichar o muro de um prédio sem autorização é crime; um grafite autorizado não é.', '["Assertiva que considera crime o grafite artístico consentido pelo proprietário erra."]'::jsonb, '[{"termo":"Grafite","significado":"Manifestação artística em muros, com consentimento."}]'::jsonb, '["Art. 63"]'::jsonb, 'under_review', 'claude'
