select u.id, u.content_sha256, 'Obstar ou dificultar a ação fiscalizadora do Poder Público no trato de questões ambientais: detenção de um a três anos, e multa.', '["Obstar ou dificultar a fiscalização ambiental.","Detenção de um a três anos e multa."]'::jsonb, '["Alcança qualquer obstáculo à fiscalização."]'::jsonb, 'Impedir a entrada de fiscais do órgão ambiental na propriedade é crime.', '["Assertiva que exige violência para o crime erra: basta obstar ou dificultar."]'::jsonb, '[]'::jsonb, '["Art. 68"]'::jsonb, 'under_review', 'claude'
