insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Elaborar ou apresentar, no licenciamento, concessão florestal ou outro procedimento administrativo, estudo, laudo ou relatório ambiental total ou parcialmente falso ou enganoso, inclusive por omissão: reclusão de 3 a 6 anos, e multa. Se culposo, detenção de 1 a 3 anos. A pena é aumentada de 1/3 a 2/3 se há dano significativo ao meio ambiente em decorrência do uso da informação falsa, incompleta ou enganosa.', '["Estudo, laudo ou relatório ambiental falso ou enganoso.","Reclusão de 3 a 6 anos e multa.","Culposo: detenção de 1 a 3 anos.","Aumento de 1/3 a 2/3 com dano significativo."]'::jsonb, '["ATUALIZAÇÃO: incluído por lei posterior à redação original.","Pune também a omissão."]'::jsonb, 'Apresentar relatório de impacto ambiental falso para obter a licença é crime.', '["Assertiva que restringe o crime a documentos falsos totalmente forjados erra: o parcialmente falso ou enganoso também é punido."]'::jsonb, '[]'::jsonb, '["Art. 66"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-69-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Considera-se infração administrativa ambiental toda ação ou omissão que viole as regras jurídicas de uso, gozo, promoção, proteção e recuperação do meio ambiente. São autoridades competentes para lavrar auto de infração e instaurar processo os funcionários de órgãos do SISNAMA designados para fiscalização e os agentes das Capitanias dos Portos. Qualquer pessoa, constatando infração, poderá representar às autoridades. A autoridade que tiver conhecimento da infração é obrigada a promover sua apuração imediata, sob pena de corresponsabilidade. As infrações são apuradas em processo administrativo próprio, com ampla defesa e contraditório.', '["Conceito de infração administrativa ambiental.","Autoridades competentes: SISNAMA e Capitanias dos Portos.","Qualquer pessoa pode representar.","Dever de apuração imediata.","Ampla defesa e contraditório."]'::jsonb, '["A autoridade que sabe e não apura responde junto (corresponsabilidade)."]'::jsonb, 'Qualquer cidadão pode representar ao órgão ambiental contra uma infração.', '["Assertiva que restringe a representação a pessoas com interesse direto erra: qualquer pessoa pode representar."]'::jsonb, '[{"termo":"SISNAMA","significado":"Sistema Nacional do Meio Ambiente."}]'::jsonb, '["Art. 71"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-70'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O processo administrativo para apuração de infração ambiental deve observar os prazos máximos de vinte dias para o infrator oferecer defesa ou impugnação, contados da ciência da autuação; trinta dias para a autoridade julgar o auto de infração, contados da lavratura; vinte dias para o infrator recorrer da decisão condenatória à instância superior; e cinco dias para o pagamento da multa, contados do recebimento da notificação.', '["Defesa: vinte dias.","Julgamento: trinta dias.","Recurso: vinte dias.","Pagamento da multa: cinco dias."]'::jsonb, '["Prazos: vinte dias (defesa), trinta (julgamento), vinte (recurso) e cinco (pagamento)."]'::jsonb, 'O autuado tem vinte dias para apresentar defesa.', '["Assertiva que fixa em dez dias o prazo de defesa erra: são vinte dias."]'::jsonb, '[]'::jsonb, '["Art. 70"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-71'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As infrações administrativas são punidas com advertência; multa simples; multa diária; apreensão dos animais, produtos, instrumentos, equipamentos ou veículos usados na infração; destruição ou inutilização do produto; suspensão de venda e fabricação; embargo de obra ou atividade; demolição de obra; suspensão parcial ou total de atividades; e sanção restritiva de direitos. Se o infrator cometer duas ou mais infrações, as sanções são aplicadas cumulativamente. A advertência é aplicada pela inobservância da lei. A multa simples é aplicada quando o agente, por negligência ou dolo, deixa de sanar irregularidades advertidas ou opõe embaraço à fiscalização. A multa simples pode ser convertida em serviços de preservação e recuperação ambiental. A multa diária é aplicada quando a infração se prolonga no tempo.', '["Rol de sanções administrativas.","Cumulação em caso de várias infrações.","Multa simples por não sanar irregularidade ou por embaraço à fiscalização.","Conversão da multa simples em serviços ambientais.","Multa diária quando a infração se prolonga."]'::jsonb, '["Multa simples pode ser CONVERTIDA em serviços ambientais.","Multa diária para infração continuada."]'::jsonb, 'O infrator que continua poluindo recebe multa diária.', '["Assertiva que impede a conversão da multa simples em serviços ambientais erra."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ambientais' and u.unit_key = 'art-72'
