insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os valores arrecadados em pagamento de multas por infração ambiental serão revertidos ao Fundo Nacional do Meio Ambiente, ao Fundo Naval, ao Fundo Nacional para Calamidades Públicas, Proteção e Defesa Civil e aos fundos estaduais ou municipais de meio ambiente, conforme dispuser o órgão arrecadador. Reverterão ao Fundo Nacional do Meio Ambiente 50% dos valores de multas aplicadas pela União, percentual que poderá ser alterado pelos órgãos arrecadadores.', '["Destino das multas: fundos ambientais, naval e de defesa civil.","Multas da União: 50% ao Fundo Nacional do Meio Ambiente."]'::jsonb, '["50% das multas da União vão ao Fundo Nacional do Meio Ambiente (percentual alterável)."]'::jsonb, 'Metade da multa aplicada pela União vai ao Fundo Nacional do Meio Ambiente.', '["Assertiva que destina todas as multas ao Tesouro sem vinculação erra."]'::jsonb, '[]'::jsonb, '["Art. 72"]'::jsonb, 'under_review', 'claude'
