insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Resguardados a soberania nacional, a ordem pública e os bons costumes, o Governo brasileiro prestará, no que concerne ao meio ambiente, a necessária cooperação a outro país, sem qualquer ônus, quando solicitado para produção de prova, exame de objetos e lugares, informações sobre pessoas e coisas, presença temporária da pessoa presa cujas declarações tenham relevância e outras formas de assistência permitidas. A solicitação será dirigida ao Ministério da Justiça, que a remeterá ao órgão competente, e deverá conter a qualificação da autoridade, o objeto e motivo, a descrição do procedimento, a assistência solicitada e a documentação necessária.', '["Cooperação internacional sem ônus.","Produção de prova, exame de lugares e informações.","Solicitação dirigida ao Ministério da Justiça.","Requisitos do pedido."]'::jsonb, '["A solicitação passa pelo Ministério da Justiça."]'::jsonb, 'Um país pede ao Brasil provas sobre crime ambiental transnacional, e o pedido vai ao Ministério da Justiça.', '["Assertiva que cobra ônus do país solicitante erra: a cooperação é sem qualquer ônus."]'::jsonb, '[]'::jsonb, '["Art. 78"]'::jsonb, 'under_review', 'claude'
