insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos ambientais integrantes do SISNAMA ficam autorizados a celebrar, com força de título executivo extrajudicial, termo de compromisso com pessoas físicas ou jurídicas responsáveis por estabelecimentos e atividades que utilizem recursos ambientais, efetiva ou potencialmente poluidores. O termo destina-se exclusivamente a permitir que corrijam suas atividades para atender às exigências ambientais, e deve dispor, entre outros pontos, sobre as partes, o prazo de vigência, que pode variar de noventa dias a três anos, prorrogável por igual período, a descrição do objeto, o valor do investimento e o cronograma, com metas trimestrais.', '["Termo de compromisso com força de título executivo extrajudicial.","Finalidade: corrigir atividades poluidoras.","Prazo de noventa dias a três anos, prorrogável por igual período.","Cronograma com metas trimestrais."]'::jsonb, '["ATUALIZAÇÃO: incluído por medida provisória e lei posteriores; confira a redação vigente.","Título executivo EXTRAJUDICIAL."]'::jsonb, 'A empresa assina termo de compromisso para adequar sua operação às exigências ambientais.', '["Assertiva que fixa o prazo do termo em até cinco anos erra: varia de noventa dias a três anos, prorrogável por igual período."]'::jsonb, '[]'::jsonb, '["Art. 72"]'::jsonb, 'under_review', 'claude'
