insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Juizado Especial Cível tem competência para conciliação, processo e julgamento das causas cíveis de menor complexidade: as de valor até quarenta vezes o salário mínimo; as enumeradas no art. 275, inciso II, do antigo Código de Processo Civil; a ação de despejo para uso próprio; e as ações possessórias sobre imóveis de valor não excedente ao limite. Compete-lhe promover a execução dos seus julgados e dos títulos executivos extrajudiciais até quarenta vezes o salário mínimo. Ficam excluídas as causas de natureza alimentar, falimentar, fiscal e de interesse da Fazenda Pública, as relativas a acidentes de trabalho, a resíduos e ao estado e capacidade das pessoas. A opção pelo procedimento importa renúncia ao crédito excedente ao limite, salvo conciliação.', '["Teto: quarenta vezes o salário mínimo.","Despejo para uso próprio e ações possessórias de imóveis dentro do teto.","Execução dos julgados e de títulos extrajudiciais até o teto.","Exclusões: alimentar, falimentar, fiscal, Fazenda Pública, acidentes de trabalho, resíduos e estado e capacidade das pessoas.","Renúncia ao excedente, salvo conciliação."]'::jsonb, '["Teto de quarenta salários mínimos.","A opção pelo Juizado implica RENÚNCIA ao crédito excedente (exceto na conciliação)."]'::jsonb, 'Quem cobra vinte mil reais em dívida simples pode propor a ação no Juizado Especial.', '["Assertiva que permite ao Juizado Cível julgar causas de natureza fiscal erra: elas são excluídas."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
